"""The Lie conformal subalgebra C of V^c generated by T and Lambda (closed under d = L_{-1} and
all j-products, j >= 0), truncated at weight W.  A_c is generated by A_c^{<=4} iff
C_n + dV_{n-1} = V_n for every n (Lemma 11.7.1).  Prints dim of (C_n + dV_{n-1})/dV_{n-1}
against dim K_n = p(n) - p(n-1).
Statement 11.7.4, headings 1) and 2): reached = dim K_n for every n <= W.
Run:  python3 conf.py 7/3 12   (about a minute),  python3 conf.py 1 10   (a few seconds)."""
import sys
import os; sys.path[:0] = [os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "lib"), os.path.dirname(os.path.abspath(__file__))]
from exactlin import rank, rref
from va import VA, parts
from fractions import Fraction as Fr

def run(c, W):
    V = VA(Fr(c))
    B = {n: parts(n) for n in range(0, W + 1)}
    def vec(st, n): return [st.get(p, Fr(0)) for p in B[n]]
    def tostate(v, n): return {p: x for p, x in zip(B[n], v) if x}
    C = {n: [] for n in range(2, W + 1)}       # row-reduced bases
    def add(st):
        if not st: return False
        n = sum(next(iter(st)))
        if n > W or n < 2: return False
        v = vec(st, n)
        if rank(C[n] + [v]) > len(C[n]):
            C[n] = rref(C[n] + [v])[0]; C[n] = [r for r in C[n] if any(r)]
            return True
        return False
    add({(2,): Fr(1)}); add({(2, 2): Fr(1), (4,): Fr(-3, 5)})
    changed = True
    while changed:
        changed = False
        # d-closure
        for n in range(2, W):
            for r in list(C[n]):
                if add(V.L(-1, tostate(r, n))): changed = True
        for p in range(2, W + 1):
            for q in range(2, W + 1):
                for a in list(C[p]):
                    for b in list(C[q]):
                        for j in range(0, p + q):
                            if p + q - j - 1 > W or p + q - j - 1 < 2: continue
                            st = V.mode(tostate(a, p), j, tostate(b, q))
                            st = {k: v for k, v in st.items() if k != ()}
                            if add(st): changed = True
    out = {}
    for n in range(2, W + 1):
        dV = [vec(V.L(-1, {u: Fr(1)}), n) for u in B[n - 1]] if n > 2 else []
        rd = rank(dV) if dV else 0
        out[n] = (rank(C[n] + dV) - rd if C[n] or dV else 0, len(B[n]) - (len(B[n - 1]) if n > 2 else 0))
    return out

if __name__ == "__main__":
    c = Fr(sys.argv[1]); W = int(sys.argv[2])
    o = run(c, W)
    print("c =", c, "W =", W, " n: reached/dim K_n:", " ".join(f"{n}:{a}/{b}" for n, (a, b) in o.items()))
